"""Worker B · writes tests/b-policy-matrix.md
   1. parses supabase/schema.sql with pglast (every statement must parse) and lists
      tables, RLS, policies, grants, triggers and functions found in the parse tree;
   2. asks the real policy module (public/vendor/fta-policy.js, via node) who may read
      and write each collection, so the table is generated, never hand-written.
   Run: python3 tests/b-policy-matrix.py"""
import json, os, subprocess, pglast
from pglast import ast
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sql = open(os.path.join(ROOT, 'supabase', 'schema.sql')).read()
stmts = pglast.parse_sql(sql)
tables, rls, force, pols, grants, revokes, trigs, funcs, idx, other = [], set(), set(), [], [], [], [], [], [], []
name = lambda r: '.'.join(x for x in [r.schemaname, r.relname] if x)
for s in stmts:
    n = s.stmt
    if isinstance(n, ast.CreateStmt): tables.append(name(n.relation))
    elif isinstance(n, ast.AlterTableStmt):
        for c in n.cmds:
            if c.subtype == pglast.enums.AlterTableType.AT_EnableRowSecurity: rls.add(name(n.relation))
            if c.subtype == pglast.enums.AlterTableType.AT_ForceRowSecurity: force.add(name(n.relation))
    elif isinstance(n, ast.CreatePolicyStmt): pols.append((n.policy_name, name(n.table), n.cmd_name, ','.join(r.rolename for r in n.roles)))
    elif isinstance(n, ast.GrantStmt):
        objs = ', '.join(name(o) if isinstance(o, ast.RangeVar) else '.'.join(x.sval for x in o.objname) if isinstance(o, ast.ObjectWithArgs) else str(o) for o in (n.objects or []))
        privs = ', '.join(p.priv_name for p in n.privileges) if n.privileges else 'ALL'
        (grants if n.is_grant else revokes).append((privs, objs, ', '.join(g.rolename or 'PUBLIC' for g in n.grantees)))
    elif isinstance(n, ast.CreateTrigStmt): trigs.append((n.trigname, name(n.relation), '.'.join(x.sval for x in n.funcname)))
    elif isinstance(n, ast.CreateFunctionStmt):
        opts = {o.defname: o.arg for o in n.options}
        funcs.append(('.'.join(x.sval for x in n.funcname), 'security definer' if 'security' in opts and opts['security'].boolval else 'invoker'))
    elif isinstance(n, ast.IndexStmt): idx.append((n.idxname, name(n.relation)))
    else: other.append(type(n).__name__)
pol = subprocess.run(['node', '-e', r'''
const P = require(process.argv[1]);
const R = P.ROLES, cls = { 'Money (invoices, payments, expenses, payroll, accounts …)': P.MONEY, 'People (students, enrolments, teachers, programmes, portals)': P.PEOPLE, 'School (classes, attendance, homework, exams, marks …)': P.TEACH, 'Notices, circles, requests': P.COMMS, 'Settings (organisation, permissions, papers, lists)': P.SETTINGS, 'Office only (notes, bin, audit)': ['notes', 'bin', 'audit'] };
const me = r => ({ email: 'x@gmail.com', role: r, active: true, mentor_id: 'MEN-01', student_id: 'STU-1001' });
const ctx = { get: () => null, all: () => [] };
const rows = {};
for (const [k, list] of Object.entries(cls)) rows[k] = R.map(r => { const read = list.filter(c => P.canSee(me(r), c)), write = list.filter(c => { const w = P.write(me(r), c, 'ID-1', { id: 'ID-1', status: 'Pending', mentor: 'MEN-01', by: 'MEN-01', from: r === 'Mentor' ? 'men:MEN-01' : 'stu:STU-1001' }, null, ctx, Date.now()); return w.ok && !w.ignore; }); return { read: read.length + '/' + list.length, write: write.length + '/' + list.length, wl: write }; });
const pay = R.map(r => { const t = s => P.write(me(r), 'payments', 'PAY-1', { id: 'PAY-1', status: s }, null, ctx).ok; return (t('Pending') ? 'Pending ' : '') + (t('Verified') ? 'Verified' : ''); });
const mem = R.map(r => ['Owner', 'Admin', 'Finance Manager', 'Mentor', 'Student'].filter(t => P.memberWrite(me(r), { email: 'n@gmail.com', role: t, mentor_id: 'MEN-9', student_id: 'STU-9' }, null).ok).join(', ') || '—');
console.log(JSON.stringify({ R, rows, pay, mem }));
''', os.path.join(ROOT, 'public', 'vendor', 'fta-policy.js')], capture_output=True, text=True, check=True)
P = json.loads(pol.stdout)
R = P['R']
L = []
w = L.append
w('# FTA Command Centre · access policy matrix')
w('')
w('Generated by `tests/b-policy-matrix.py` (worker B). Section 1 comes from parsing `supabase/schema.sql` with **pglast ' + pglast.__version__ + '**; section 2 is produced by running the real policy module `public/vendor/fta-policy.js` (the same code the Netlify Function and the mock backend use), so this table cannot drift from the code.')
w('')
w('## 1. Database (schema.sql) — %d statements, all parsed' % len(stmts))
w('')
w('| Table | Row Level Security | Forced | Direct policies |')
w('|---|---|---|---|')
for t in tables:
    tp = [p for p in pols if p[1].split('.')[-1] == t.split('.')[-1]]
    w('| `%s` | %s | %s | %s |' % (t, 'on' if t in rls else '**off**', 'yes' if t in force else 'no', '; '.join('%s: %s to %s' % (p[0], p[2], p[3]) for p in tp) or 'none (deny all)'))
w('')
w('- **Revoked:** ' + '; '.join('%s on %s from %s' % r for r in revokes))
w('- **Granted:** ' + '; '.join('%s on %s to %s' % g for g in grants))
w('- **Triggers:** ' + '; '.join('`%s` on %s → %s()' % t for t in trigs))
w('- **Functions:** ' + ', '.join('`%s()` (%s)' % f for f in funcs))
w('- **Indexes:** ' + ', '.join('`%s`' % i[0] for i in idx))
w('- **Storage:** private bucket `files` (25 MB, no public access, no storage policies: access only through signed URLs issued by the server).')
w('')
w('What this means: with the public anon key nobody can read or change anything. A signed-in user cannot write any table directly; the Owner alone can *read* `records`, `members` and `audit_log` (for Supabase dashboard queries). Every app read and write goes through the Netlify Function (`/api`), which uses the service-role key and applies section 2. `audit_log` cannot be updated or deleted (trigger), and the last active Owner cannot be deleted, demoted or switched off (trigger). Verified on a real PostgreSQL 16 with `tests/b-pg-check.sql` (output in `tests/b-pg-check.out`).')
w('')
w('## 2. App rules (server-side, per collection group)')
w('')
w('Read = collections of the group this role receives (always filtered and redacted for teachers and students). Write = collections it may change.')
w('')
w('| Group | ' + ' | '.join(R) + ' |')
w('|---|' + '---|' * len(R))
for k, row in P['rows'].items():
    w('| %s | %s |' % (k, ' | '.join('R %s · W %s' % (c['read'], c['write']) for c in row)))
w('| Payments a role can create | ' + ' | '.join(x or '—' for x in P['pay']) + ' |')
w('| Sign-in accounts it can add | ' + ' | '.join(P['mem']) + ' |')
w('')
w('### Row filters and redaction (teachers and students)')
w('')
w('- **Teacher (Mentor):** receives only records tagged with their own teacher id. Tags are computed **on the server** from the record (`MEN-…`/`STU-…` ids, class-group membership, enrolment teacher), never trusted from the browser, and refreshed when a class group or enrolment changes. Students: no office notes; enrolments: no fees, discounts; programmes: no fee; batches: no teacher pay; other teachers: name, subjects and status only; payroll: only their own lines (who, method, amount); no invoices, payments, expenses, accounts, transfers, budgets, bank balances or academy share. May write attendance, homework, class notes, marks (not approve), leave reports, events, routine of their own classes; may only *request* a student portal (saved inactive until the office approves).')
w('- **Student:** only their own student record, enrolments (no fees), class groups (showing only themself), attendance and remarks for themself, approved/published marks (own score only), homework for them, class notes for them or the whole class, published notices, online exams for their class (answer keys stripped), their own attempts (start time and deadline set by the server, marks kept by the server). Can change nothing else.')
w('- **Collection Staff:** students (read), invoices and payments; may create and edit **Pending** payments only (Finance verifies); follow-ups and notes. Teachers: name, subjects, phone; accounts: name and type only.')
w('- **Finance Manager:** all money collections and people records; cannot change school records, permissions, settings or sign-in accounts.')
w('- **Junior Admin:** front office (people, school, notices); no money except creating Pending payments; cannot change fees or discounts; cannot delete; can give sign-in access to teachers and students only.')
w('- **Admin:** everything except Owner-only settings (permissions, organisation, papers, messages, look) and cannot add, change or remove the Owner or other Admins.')
w('- **Owner:** everything. Only the Owner can add or remove Admins. The Owner cannot remove themself, and the last active Owner can never be removed (database trigger).')
w('- **Viewer:** reads office data (not the audit trail), changes nothing.')
w('- **Everyone:** a change is refused if the record changed on the server since the person last saw it (optimistic concurrency → “someone else changed this”); activity log and audit lines are append-only.')
open(os.path.join(ROOT, 'tests', 'b-policy-matrix.md'), 'w').write('\n'.join(L) + '\n')
print('statements:', len(stmts), 'tables:', tables, 'rls:', sorted(rls), 'forced:', sorted(force), 'policies:', len(pols), 'triggers:', len(trigs))
